mapper.select:
SELECT REGIST_SEQNO registSeqno, SALER_INST_CODE salerInstCode, SALER_ORG_CODE salerOrgCode, SALER_ORG_NAME salerOrgName, SALER_ORG_LEVEL salerOrgLevel, SEND_STATUS sendStatus, SUBMIT_FEEDBACK_MSG submitFeedbackMsg, SUBMIT_FEEDBACK_STATUS submitFeedbackStatus, SUBMIT_TIME submitTime, CHB_SUBMIT_DEADLINE chbSubmitDeadline, SUBMIT_DEADLINE submitDeadline, STATUS status, SUMIT_SEQ sumitSeq, DATA_DATE dataDate, UPDATE_TIME FROM CHB_SALER_INST_SUB where 1=1
and SALER_INST_CODE like concat('%',concat(#{salerInstCode,jdbcType=VARCHAR},'%'))
and SALER_ORG_NAME like concat('%',concat(#{salerOrgName,jdbcType=VARCHAR},'%'))
and SUBMIT_FEEDBACK_STATUS = #{submitFeedbackStatus}
and SEND_STATUS = #{sendStatus}
and CHB_SUBMIT_DEADLINE between to_date(#{searchSubmitDeadlineStart,jdbcType=VARCHAR},'yyyy-mm-dd') and to_date(#{searchSubmitDeadlineEnd,jdbcType=VARCHAR},'yyyy-mm-dd')
and to_char(DATA_DATE,'yyyy-MM-dd') >= #{searchDataDateStart,jdbcType=VARCHAR}
and to_char(DATA_DATE,'yyyy-MM-dd') <= #{searchDataDateEnd,jdbcType=VARCHAR}
and to_char(SUBMIT_TIME,'yyyy-MM-dd') >= #{searchSubmitTimeStart,jdbcType=VARCHAR}
and to_char(SUBMIT_TIME,'yyyy-MM-dd') <= #{searchSubmitTimeEnd,jdbcType=VARCHAR}
#{status}
ORDER BY UPDATE_TIME DESC

