mapper.update:
update CHB_SALER_INST_SUB
SEND_STATUS = '01', SUBMIT_TIME = null, SUBMIT_FEEDBACK_STATUS = null
trim(REGIST_SEQNO) = #{dto.registSeqno}

mapper.insert:
insert into CHB_SALER_INST_SUB ( REGIST_SEQNO, SALER_INST_CODE,SALER_ORG_CODE,SALER_ORG_NAME,SALER_ORG_LEVEL, STATUS,CHB_SUBMIT_DEADLINE,SUBMIT_DEADLINE, DATA_DATE,SUBMIT_TIME,SUMIT_SEQ, SEND_STATUS, SUBMIT_FEEDBACK_STATUS,SUBMIT_FEEDBACK_MSG,CREATE_DEPT,ORG_CODE, CREATE_USER,CREATE_TIME,UPDATE_USER,UPDATE_TIME) select HIS_NO, SALER_INST_CODE,SALER_ORG_CODE,SALER_ORG_NAME,SALER_ORG_LEVEL, STATUS, CHB_SUBMIT_DEADLINE,SUBMIT_DEADLINE, DATA_DATE,SUBMIT_TIME,SUMIT_SEQ,SEND_STATUS, SUBMIT_FEEDBACK_STATUS,SUBMIT_FEEDBACK_MSG,CREATE_DEPT,ORG_CODE, CREATE_USER,his.CREATE_TIME,UPDATE_USER,UPDATE_TIME from CHB_SALER_INST_SUB_HIS his INNER join ( SELECT max(CREATE_TIME) CREATE_TIME from CHB_SALER_INST_SUB_HIS
SALER_ORG_CODE IN
#{regist.salerOrgCode,jdbcType=VARCHAR}
) maxtime on his.CREATE_TIME=maxtime.CREATE_TIME

